-- 4_monitoring: disclosed work-activity monitoring (settings, employee consent, paired devices, raw samples,
-- daily summaries, offline/tamper alerts).
--
-- ADDITIVE AND IDEMPOTENT. Every statement is guarded (IF NOT EXISTS / duplicate_object), no drops, renames or type
-- changes, so it is safe to apply to a database built by any earlier migration and safe to apply twice. Monitoring is
-- OFF by default (MonitoringSettings.enabled defaults to false); existing tenants and rows are untouched.
-- Generated by scripts/gen-migration.sh (prisma migrate diff, then scripts/idempotent-migration.py), header edited.

CREATE TABLE IF NOT EXISTS "MonitoringSettings" (
    "tenantId" TEXT NOT NULL,
    "enabled" BOOLEAN NOT NULL DEFAULT false,
    "policyText" TEXT NOT NULL DEFAULT '',
    "policyVersion" INTEGER NOT NULL DEFAULT 1,
    "trackApps" BOOLEAN NOT NULL DEFAULT true,
    "trackDomains" BOOLEAN NOT NULL DEFAULT true,
    "workdayStartMin" INTEGER NOT NULL DEFAULT 540,
    "workdayEndMin" INTEGER NOT NULL DEFAULT 1080,
    "offlineAlertMins" INTEGER NOT NULL DEFAULT 15,
    "retentionRawDays" INTEGER NOT NULL DEFAULT 30,
    "retentionSummaryDays" INTEGER NOT NULL DEFAULT 365,
    "updatedByUserId" TEXT,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "MonitoringSettings_pkey" PRIMARY KEY ("tenantId")
);

CREATE TABLE IF NOT EXISTS "MonitoringConsent" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "policyVersion" INTEGER NOT NULL,
    "acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ipAddress" TEXT,

    CONSTRAINT "MonitoringConsent_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "MonitoredDevice" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "platform" TEXT,
    "agentVersion" TEXT,
    "tokenHash" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "pairedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lastSeenAt" TIMESTAMP(3),
    "lastAlertAt" TIMESTAMP(3),
    "revokedAt" TIMESTAMP(3),

    CONSTRAINT "MonitoredDevice_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ActivitySample" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "deviceId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "windowStart" TIMESTAMP(3) NOT NULL,
    "windowEnd" TIMESTAMP(3) NOT NULL,
    "activeSeconds" INTEGER NOT NULL DEFAULT 0,
    "idleSeconds" INTEGER NOT NULL DEFAULT 0,
    "mouseEvents" INTEGER NOT NULL DEFAULT 0,
    "keyboardEvents" INTEGER NOT NULL DEFAULT 0,
    "foregroundApp" TEXT,
    "foregroundDomain" TEXT,
    "category" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ActivitySample_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "ActivityDailySummary" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "day" TEXT NOT NULL,
    "activeSeconds" INTEGER NOT NULL DEFAULT 0,
    "idleSeconds" INTEGER NOT NULL DEFAULT 0,
    "offlineSeconds" INTEGER NOT NULL DEFAULT 0,
    "firstActivityAt" TIMESTAMP(3),
    "lastActivityAt" TIMESTAMP(3),
    "topApps" JSONB,
    "mouseEvents" INTEGER NOT NULL DEFAULT 0,
    "keyboardEvents" INTEGER NOT NULL DEFAULT 0,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ActivityDailySummary_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "MonitoringAlert" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "employeeId" TEXT NOT NULL,
    "deviceId" TEXT,
    "type" TEXT NOT NULL,
    "detail" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "resolvedAt" TIMESTAMP(3),
    "resolvedByUserId" TEXT,

    CONSTRAINT "MonitoringAlert_pkey" PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "MonitoringConsent_tenantId_employeeId_idx" ON "MonitoringConsent"("tenantId", "employeeId");

CREATE UNIQUE INDEX IF NOT EXISTS "MonitoringConsent_tenantId_employeeId_policyVersion_key" ON "MonitoringConsent"("tenantId", "employeeId", "policyVersion");

CREATE UNIQUE INDEX IF NOT EXISTS "MonitoredDevice_tokenHash_key" ON "MonitoredDevice"("tokenHash");

CREATE INDEX IF NOT EXISTS "MonitoredDevice_tenantId_employeeId_idx" ON "MonitoredDevice"("tenantId", "employeeId");

CREATE INDEX IF NOT EXISTS "MonitoredDevice_tenantId_lastSeenAt_idx" ON "MonitoredDevice"("tenantId", "lastSeenAt");

CREATE INDEX IF NOT EXISTS "ActivitySample_tenantId_employeeId_windowStart_idx" ON "ActivitySample"("tenantId", "employeeId", "windowStart");

CREATE INDEX IF NOT EXISTS "ActivitySample_tenantId_createdAt_idx" ON "ActivitySample"("tenantId", "createdAt");

CREATE INDEX IF NOT EXISTS "ActivityDailySummary_tenantId_day_idx" ON "ActivityDailySummary"("tenantId", "day");

CREATE UNIQUE INDEX IF NOT EXISTS "ActivityDailySummary_tenantId_employeeId_day_key" ON "ActivityDailySummary"("tenantId", "employeeId", "day");

CREATE INDEX IF NOT EXISTS "MonitoringAlert_tenantId_resolvedAt_idx" ON "MonitoringAlert"("tenantId", "resolvedAt");

CREATE INDEX IF NOT EXISTS "MonitoringAlert_tenantId_employeeId_idx" ON "MonitoringAlert"("tenantId", "employeeId");

DO $$ BEGIN
  ALTER TABLE "MonitoringSettings" ADD CONSTRAINT "MonitoringSettings_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

